// Q-L1-16 T12: the CPU's SDRAM commands (psx.WRAM_READ/WRAM_WRITE/BIOS_READ) are issued
// without looking at sdram_ack. One that arrives while a GPU/SPU command is in flight
// (gpu_*_wait_ack/spu_wait_ack) is held in cpu_pend_* and issued when that command
// completes; the ack level reaches the CPU only while no GPU/SPU command is in flight
// and no CPU command is held (the level semantics of the original ack are kept).
instrself cpu_read(cpu_adrs, cpu_burst);
instrself cpu_write(cpu_adrs, cpu_din, cpu_enable, cpu_burst);
sel cpu_adrs<25>, cpu_din<128>, cpu_enable<16>, cpu_burst<4>;
reg_wr cpu_pend, cpu_pend_write;
reg cpu_pend_adrs<25>, cpu_pend_din<128>, cpu_pend_enable<16>, cpu_pend_burst<4>;
sel alt_busy;
alt_busy = gpu_read_wait_ack | gpu_write_wait_ack | spu_wait_ack;

instruct psx.WRAM_READ par{
	any{
		(psx.Word==1) | (psx.Word==2) : par{
			cpu_read(0b00000 || psx.A<20:1>, 1);
		}
		else : par{// byte 16,12,8,4 -> burst 8,6,4,2
			cpu_read(0b00000 || psx.A<20:2> || 0b0, psx.Word<4:1>);
		}

}
instruct cpu_read par{
	if(alt_busy){
		cpu_pend := 0b1;
		cpu_pend_write := 0b0;
		cpu_pend_adrs := cpu_adrs;
		cpu_pend_burst := cpu_burst;
	}
	else sdram_read(cpu_adrs, cpu_burst);
}
instruct cpu_write par{
	if(alt_busy){
		cpu_pend := 0b1;
		cpu_pend_write := 0b1;
		cpu_pend_adrs := cpu_adrs;
		cpu_pend_din := cpu_din;
		cpu_pend_enable := cpu_enable;
		cpu_pend_burst := cpu_burst;
	}
	else sdram_write(cpu_adrs, cpu_din, cpu_enable, cpu_burst);
}
if(cpu_pend & sdram_ack){ // the GPU/SPU command has completed: issue the held one
	if(cpu_pend_write) sdram_write(cpu_pend_adrs, cpu_pend_din, cpu_pend_enable, cpu_pend_burst);
	else sdram_read(cpu_pend_adrs, cpu_pend_burst);
	cpu_pend := 0b0;
}
if(sdram_ack & ^alt_busy & ^cpu_pend){
	psx.wram_ack();
	psx.bios_ack();
}

